17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.rest.validation.CustomerCodeGenerator;
39	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
40	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
41	import org.springframework.samples.petclinic.rest.validation.OwnerHouseholdUniquenessValidator;
42	import org.springframework.samples.petclinic.rest.validation.OwnerTelephoneUniquenessValidator;
43	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final PetMapper petMapper;
67	
68	    private final VisitMapper visitMapper;
69	
70	    private final OwnerTelephoneUniquenessValidator telephoneUniquenessValidator;
71	
72	    private final OwnerHouseholdUniquenessValidator householdUniquenessValidator;
73	
74	    public OwnerRestControllerV1(ClinicService clinicService,
75	                                 OwnerMapper ownerMapper,
76	                                 PetMapper petMapper,
77	                                 VisitMapper visitMapper,
78	                                 OwnerTelephoneUniquenessValidator telephoneUniquenessValidator,
79	                                 OwnerHouseholdUniquenessValidator householdUniquenessValidator) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	        this.telephoneUniquenessValidator = telephoneUniquenessValidator;
85	        this.householdUniquenessValidator = householdUniquenessValidator;
86	    }
87	
88	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
89	    @Override
90	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
91	        Collection<Owner> owners;
92	        if (lastName != null) {
93	            owners = this.clinicService.findOwnerByLastName(lastName);
94	        } else {
95	            owners = this.clinicService.findAllOwners();
96	        }
97	        if (owners.isEmpty()) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
106	        Owner owner = this.clinicService.findOwnerById(ownerId);
107	        if (owner == null) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        OwnerFieldsValidator.validateRequiredFields(ownerFieldsDto);
117	        HttpHeaders headers = new HttpHeaders();
118	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
119	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
120	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
121	        this.telephoneUniquenessValidator.validateUnique(owner.getTelephone());
122	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
123	            this.householdUniquenessValidator.validateUnique(owner.getLastName(), owner.getAddress());
124	        }
125	        owner.setCustomerCode(CustomerCodeGenerator.generate(owner.getLastName(), this.clinicService.countOwners()));
126	        this.clinicService.saveOwner(owner);
127	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
128	        headers.setLocation(UriComponentsBuilder.newInstance()
129	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
130	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
136	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
137	        if (currentOwner == null) {
138	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
139	        }
140	        currentOwner.setAddress(ownerFieldsDto.getAddress());
141	        currentOwner.setCity(ownerFieldsDto.getCity());
142	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
143	        currentOwner.setLastName(ownerFieldsDto.getLastName());
144	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
145	        this.clinicService.saveOwner(currentOwner);
146	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
147	    }
148	
